  "chat.example1Prompt": "Tạo a 10-slide investor roadshow deck for a seed-stage thiết kế studio. Include cover, problem, insight, product, market, traction, business mô hình, team, ask, and contact. Editorial polish, crisp charts, strong narrative, and enough restraint for an investor meeting.",
  "chat.example2Title": "Notes app landing page",
  "chat.example2Tag": "Landing",
  "chat.example2Prompt": "Thiết kế a landing page for an AI notes app that captures meetings, searches highlights, and turns notes into tasks. Include hero, product xem trước, feature story, social proof, pricing, FAQ, and CTA. Calm productivity aesthetic with a xóa sạch conversion path.",
