  "designFiles.documentTemplate.goalHeading": "Goal",
  "designFiles.documentTemplate.goalBody": "Describe what OpenDesign should generate, chỉnh sửa, or decide from this document.",
  "designFiles.documentTemplate.capabilitiesHeading": "How to use this document",
  "designFiles.documentTemplate.capabilityMarkdown": "Use any Markdown format: headings, tables, checklists, links, quotes, code blocks, and images.",
  "designFiles.documentTemplate.capabilityAgent": "The OpenDesign tác tử can read, chỉnh sửa, and use this file as dự án context.",
  "designFiles.documentTemplate.capabilityImages": "Paste images, or drag image files onto the editor; uploaded images are inserted at the cursor.",
  "designFiles.documentTemplate.scenarioHeading": "Scenario guide",
  "designFiles.documentTemplate.scenario.prototype": "For prototypes, outline the product goal, target users, flows, screens, modules, interaction states, responsive breakpoints, and thiết kế tokens such as color, type, spacing, radius, and motion.",
  "designFiles.documentTemplate.scenario.wireframe": "For wireframes, describe the người dùng flow, screen list, layout hierarchy, content blocks, low-fidelity constraints, and the questions the structure should answer before visual thiết kế.",
  "designFiles.documentTemplate.scenario.mobile": "For mobile apps, list target platforms, screens, navigation mô hình, gestures, native patterns, device sizes, states, and mobile thiết kế tokens.",
  "designFiles.documentTemplate.scenario.slideDeck": "For slides, write a paginated PPT outline: one section per slide with tiêu đề, purpose, key message, evidence, visual direction, speaker notes, and xuất needs.",
  "designFiles.documentTemplate.scenario.document": "For documents, define audience, tone, section structure, source material, citations or data, layout expectations, and PDF/xuất requirements.",
  "designFiles.documentTemplate.scenario.image": "For images, specify subject, aspect ratio, composition, visual style, brand tokens, reference files, and negative constraints.",
  "designFiles.documentTemplate.scenario.video": "For video, bản nháp a storyboard with scenes, timing, captions, motion, assets, audio notes, and output format.",
  "designFiles.documentTemplate.scenario.hyperframes": "For HyperFrames, describe the HTML motion piece: scenes, timeline, captions, audio-reactive moments, transitions, and capture/xuất requirements.",
  "designFiles.documentTemplate.scenario.audio": "For audio, define voice or music direction, duration, mood, script or sao chép, pacing, pronunciation notes, and final use.",
  "designFiles.documentTemplate.scenario.liveArtifact": "For live tạo phẩm, describe data sources, refresh cadence, widgets, filters, interactions, empty/đang tải/lỗi states, and any alerts or tự động hóa.",
  "designFiles.documentTemplate.scenario.designSystem": "For hệ thống thiết kế, list brand goals, tokens, typography, color, spacing, components, assets, references, and rules to follow or avoid.",
  "designFiles.documentTemplate.scenario.default": "Describe the audience, deliverable, bắt buộc content, references, constraints, and what xong should look like.",
  "designFiles.documentTemplate.nextHeading": "Tiếp theo step",
