  "nextStep.planGenerateTitle": "Generate tạo phẩm",
  "nextStep.planGenerateBody": "Use the approved Markdown plan as the source of truth for the tiếp theo thiết kế run.",
  "nextStep.planImproveTitle": "Improve document",
  "nextStep.planImproveBody": "Tighten the current plan document before generating the final tạo phẩm.",
  "nextStep.planGeneratePrompt": "Use `{file}` as the source of truth. Read the document first, preserve its decisions, then generate the final thiết kế tạo phẩm that matches it. If it is a slide outline, generate the deck; if it is a PRD/prototype plan, generate the prototype or wireframes; if it is a storyboard/creative brief, generate the matching visual/media tạo phẩm. Before generating, call out any blocking TODOs or contradictions you cannot resolve.",
  "nextStep.planImprovePrompt": "Read `{file}` and improve it in place as an editable plan document. Tighten scope, fill weak sections, add missing acceptance checks, and keep TODO/open questions where người dùng input is still needed. Do not generate the final thiết kế tạo phẩm yet.",
  "nextStep.planImproveArtifactTitle": "Improve tạo phẩm",
  "nextStep.planImproveArtifactBody": "Keep iterating the generated tạo phẩm instead of going quay lại to planning.",
  "nextStep.planImproveArtifactPrompt": "Improve `{artifact}` in place. Keep the existing working tạo phẩm and make the highest-impact product, visual, interaction, and content improvements. Preserve behavior that already works, then summarize changed files and any remaining risks.",
  "nextStep.planMergeTitle": "Align document and tạo phẩm",
  "nextStep.planMergeBody": "Reconcile the plan and generated tạo phẩm so they advance together.",
  "nextStep.planMergePrompt": "Read `{document}` and `{artifact}` together. Treat the document as the intent and the tạo phẩm as the current implementation. Reconcile them: update the tạo phẩm to match confirmed decisions, update the document only where it is stale, and keep explicit TODO/open questions for anything still unresolved. Preserve existing working behavior and summarize what changed in both files.",
